import httpx

BASE_URL = "https://api.openweathermap.org/data/2.5/weather"
FORECAST_URL = "https://api.openweathermap.org/data/2.5/forecast"


class WeatherAPIError(Exception):
    pass


def _request(url: str, params: dict) -> dict:
    try:
        response = httpx.get(url, params=params, timeout=10)
    except httpx.ConnectError:
        raise WeatherAPIError("Could not connect to the weather service. Check your internet connection.")
    except httpx.TimeoutException:
        raise WeatherAPIError("Request timed out. The weather service may be slow — try again.")
    except httpx.HTTPError as exc:
        raise WeatherAPIError(f"Network error: {exc}")

    if response.status_code == 401:
        raise WeatherAPIError("Invalid API key. Check your OPENWEATHER_API_KEY.")
    if response.status_code == 404:
        raise WeatherAPIError(f"City not found. Check the spelling and try again.")
    if response.status_code != 200:
        raise WeatherAPIError(f"API error (HTTP {response.status_code}): {response.text}")

    return response.json()


def fetch_weather(city: str, api_key: str, units: str = "metric") -> dict:
    return _request(BASE_URL, {"q": city, "appid": api_key, "units": units})


def fetch_forecast(city: str, api_key: str, units: str = "metric") -> dict:
    return _request(FORECAST_URL, {"q": city, "appid": api_key, "units": units})

import sys

import click

from weather_cli.api import WeatherAPIError, fetch_forecast, fetch_weather
from weather_cli.display import render_forecast, render_weather


def _get_api_key(ctx: click.Context) -> str:
    api_key = ctx.obj["api_key"]
    if not api_key:
        click.echo("Error: Missing API key. Pass --api-key or set OPENWEATHER_API_KEY.", err=True)
        sys.exit(1)
    return api_key


@click.group()
@click.option(
    "--api-key",
    envvar="OPENWEATHER_API_KEY",
    help="OpenWeatherMap API key (or set OPENWEATHER_API_KEY).",
)
@click.option(
    "--units",
    type=click.Choice(["metric", "imperial", "standard"], case_sensitive=False),
    default="metric",
    help="Unit system for temperature and wind speed.",
)
@click.pass_context
def main(ctx: click.Context, api_key: str | None, units: str) -> None:
    """A CLI tool to fetch weather data by city name."""
    ctx.ensure_object(dict)
    ctx.obj["api_key"] = api_key
    ctx.obj["units"] = units


@main.command()
@click.argument("city")
@click.pass_context
def current(ctx: click.Context, city: str) -> None:
    """Show current weather for CITY."""
    api_key = _get_api_key(ctx)
    units = ctx.obj["units"]

    try:
        data = fetch_weather(city, api_key, units)
    except WeatherAPIError as exc:
        click.echo(f"Error: {exc}", err=True)
        sys.exit(1)

    render_weather(data, units)


@main.command()
@click.argument("city")
@click.option("--days", default=5, type=click.IntRange(1, 5), help="Number of days to show (1-5).")
@click.pass_context
def forecast(ctx: click.Context, city: str, days: int) -> None:
    """Show multi-day forecast for CITY."""
    api_key = _get_api_key(ctx)
    units = ctx.obj["units"]

    try:
        data = fetch_forecast(city, api_key, units)
    except WeatherAPIError as exc:
        click.echo(f"Error: {exc}", err=True)
        sys.exit(1)

    render_forecast(data, units, days)

