from unittest.mock import patch

from click.testing import CliRunner

from weather_cli.cli import main

SAMPLE_RESPONSE = {
    "name": "London",
    "sys": {"country": "GB"},
    "weather": [{"main": "Clouds", "description": "overcast clouds"}],
    "main": {"temp": 12.5, "feels_like": 11.0, "humidity": 80},
    "wind": {"speed": 3.2},
}

SAMPLE_FORECAST = {
    "city": {"name": "London", "country": "GB"},
    "list": [
        {
            "dt_txt": "2025-01-15 12:00:00",
            "main": {"temp": 10.0, "humidity": 75},
            "weather": [{"main": "Rain", "description": "light rain"}],
            "wind": {"speed": 4.0},
        },
    ],
}


def test_cli_missing_api_key():
    runner = CliRunner()
    result = runner.invoke(main, ["current", "London"], env={"OPENWEATHER_API_KEY": ""})
    assert result.exit_code != 0


@patch("weather_cli.cli.fetch_weather", return_value=SAMPLE_RESPONSE)
def test_cli_current_success(mock_fetch):
    runner = CliRunner()
    result = runner.invoke(main, ["--api-key", "fake-key", "current", "London"])
    assert result.exit_code == 0
    assert "London" in result.output
    assert "12.5" in result.output


@patch("weather_cli.cli.fetch_weather", return_value=SAMPLE_RESPONSE)
def test_cli_current_units_option(mock_fetch):
    runner = CliRunner()
    result = runner.invoke(main, ["--api-key", "fake-key", "--units", "imperial", "current", "London"])
    assert result.exit_code == 0
    mock_fetch.assert_called_once_with("London", "fake-key", "imperial")


@patch("weather_cli.cli.fetch_forecast", return_value=SAMPLE_FORECAST)
def test_cli_forecast_success(mock_fetch):
    runner = CliRunner()
    result = runner.invoke(main, ["--api-key", "fake-key", "forecast", "London"])
    assert result.exit_code == 0
    assert "London" in result.output


@patch("weather_cli.cli.fetch_forecast", return_value=SAMPLE_FORECAST)
def test_cli_forecast_days_option(mock_fetch):
    runner = CliRunner()
    result = runner.invoke(main, ["--api-key", "fake-key", "forecast", "London", "--days", "3"])
    assert result.exit_code == 0


def test_cli_help():
    runner = CliRunner()
    result = runner.invoke(main, ["--help"])
    assert result.exit_code == 0
    assert "current" in result.output
    assert "forecast" in result.output

